136.       ["keydown-ENTER", handlers.confirm, false],
137.       ["keydown-ESC", handlers.cancel, false],
138.     ];
139.     for (const [eventName, handler, repeatable] of bindings) {
140.       keyboard.on(eventName, (event: KeyboardEvent) => {
141.         if (event.timeStamp <= boundAt || (!repeatable && event.repeat)) return;
142.         handler();
143.       });
