400.   private getActions(slot: SaveSlotInfo): SaveSlotAction[] {
401.     if (this.pendingConfirmation) return ["confirm", "cancel"];
402.     if (this.copySourceSlotId) return ["confirm", "cancel"];
403. 
404.     const actions: SaveSlotAction[] = [];
405.     if (this.mode === "load" && slot.state === "valid") actions.push("load");
406.     if (this.mode === "save" && slot.kind === "manual") actions.push("save");
407.     if (slot.kind === "manual" && slot.state === "valid") actions.push("rename");
408.     if (slot.state === "valid") actions.push("copy", "export");
409.     if (
410.       slot.state !== "empty"
411.       && (this.mode === "load" || slot.kind === "manual")
412.     ) {
413.       actions.push("delete");
414.     }
415.     if (this.mode === "load" || slot.kind === "manual") actions.push("import");
416.     actions.push("close");
417.     return actions;
418.   }
