420.   private selectedDescription(slot: SaveSlotInfo): string {
421.     if (this.pendingConfirmation) {
422.       if (this.pendingConfirmation.kind === "newGame") {
423.         return "Confirm replacing Autosave with a new campaign.";
424.       }
425.       return `${ACTION_LABELS[this.pendingConfirmation.kind]} will replace or remove stored data.`;
426.     }
427.     if (this.copySourceSlotId) {
428.       return slot.slotId === this.copySourceSlotId
429.         ? "Choose a different manual slot."
430.         : `Copy into ${slot.displayName}. Existing data requires confirmation.`;
431.     }
432.     return slot.diagnostic ?? `${slot.displayName}: ${slot.state}.`;
433.   }
