435.   private readonly handleKeyDown = (event: KeyboardEvent): void => {
436.     if (!this.container) return;
437.     const handledAt = event.timeStamp || performance.now();
438.     if (
439.       event.repeat
440.       || (
441.         event.key === this.lastHandledKey
442.         && handledAt - this.lastHandledAt < 80
443.       )
444.     ) {
445.       return;
446.     }
447.     this.lastHandledKey = event.key;
448.     this.lastHandledAt = handledAt;
449.     if (event.key === "Escape") {
450.       event.preventDefault();
451.       event.stopImmediatePropagation();
452.       this.cancelOrClose();
453.       return;
454.     }
455.     if (
456.       event.key === "ArrowUp"
457.       || event.key === "w"
458.       || event.key === "W"
459.     ) {
460.       event.preventDefault();
461.       this.moveSlot(-1);
462.       return;
463.     }
464.     if (
465.       event.key === "ArrowDown"
466.       || event.key === "s"
467.       || event.key === "S"
468.     ) {
469.       event.preventDefault();
470.       this.moveSlot(1);
