557.   private createTouchControls(): void {
558.     const root = document.createElement("div");
559.     root.id = "touch-controls";
560.     root.setAttribute("aria-label", "Touch game controls");
561.     for (const definition of TOUCH_BUTTONS) {
562.       const button = document.createElement("button");
563.       button.type = "button";
564.       button.className = `touch-control ${definition.className}`;
565.       button.dataset.action = definition.action;
566.       button.textContent = definition.label;
567.       button.setAttribute("aria-label", definition.action);
568.       let lastPointerActivation = Number.NEGATIVE_INFINITY;
569.       const pulse = (): void => {
570.         const inputEvent = this.state.pulse(
571.           this.contextualizeAction(definition.action),
572.           "touch",
573.           now(),
574.         );
575.         if (inputEvent) this.dispatch(inputEvent);
576.       };
577.       button.addEventListener("pointerdown", (event) => {
578.         event.preventDefault();
579.         if (!HELD_TOUCH_ACTIONS.has(definition.action)) {
580.           inputSource.set("touch");
581.           this.updatePresentation("touch");
582.           return;
583.         }
584.         if (event.isTrusted) button.setPointerCapture(event.pointerId);
585.         const action = this.contextualizeAction(definition.action);
586.         const token = `touch:${event.pointerId}:${definition.action}`;
587.         const inputEvent = this.state.press(token, action, "touch", now());
588.         if (inputEvent) {
589.           this.dispatch(inputEvent);
590.         } else {
591.           const descriptor = this.keyForAction(action);
592.           if (descriptor) {
593.             this.pressSyntheticToken(token, descriptor, false, false);
594.           }
595.         }
596.       });
597.       const releaseHeld = (event: PointerEvent): void => {
598.         const token = `touch:${event.pointerId}:${definition.action}`;
599.         this.state.release(token);
600.         window.setTimeout(() => this.releaseSyntheticToken(token), 40);
601.         if (button.hasPointerCapture(event.pointerId)) {
602.           button.releasePointerCapture(event.pointerId);
603.         }
604.       };
605.       button.addEventListener("pointerup", (event) => {
606.         event.preventDefault();
607.         if (HELD_TOUCH_ACTIONS.has(definition.action)) {
608.           releaseHeld(event);
609.           return;
610.         }
611.         lastPointerActivation = now();
612.         pulse();
613.       });
614.       button.addEventListener("pointercancel", (event) => {
615.         if (HELD_TOUCH_ACTIONS.has(definition.action)) releaseHeld(event);
616.       });
617.       button.addEventListener("lostpointercapture", (event) => {
618.         const token = `touch:${event.pointerId}:${definition.action}`;
619.         this.state.release(token);
620.         window.setTimeout(() => this.releaseSyntheticToken(token), 40);
621.       });
622.       button.addEventListener("click", (event) => {
623.         if (HELD_TOUCH_ACTIONS.has(definition.action)) return;
624.         event.preventDefault();
625.         if (now() - lastPointerActivation <= TOUCH_CLICK_SUPPRESSION_MS) return;
626.         pulse();
627.       });
628.       root.append(button);
629.     }
630.     document.getElementById("game-inner")?.append(root);
631.     this.touchRoot = root;
632.     this.applyTouchActionAvailability();
633.   }
