635.   private applyTouchActionAvailability(context = this.getContext()): void {
636.     if (!this.touchRoot) return;
637.     for (const button of this.touchRoot.querySelectorAll<HTMLButtonElement>(
638.       ".touch-control",
639.     )) {
640.       const action = button.dataset.action;
641.       if (!isInputAction(action)) {
642.         button.hidden = true;
643.         continue;
644.       }
645.       const featureId = getInputActionFeature(action);
646.       const featureEnabled = featureId === undefined
647.         || featureAvailability.has(featureId);
648.       button.hidden = !isTouchActionAvailable(
649.         action,
650.         context,
651.         featureEnabled,
652.       );
653.     }
654.   }
