705.   private exportSlot(slotId: SaveSlotId): void {
706.     const result = exportSaveSlot(slotId);
707.     if (!result.ok) {
708.       this.setStatus(result.message, false);
709.       return;
710.     }
711.     try {
712.       const url = URL.createObjectURL(new Blob([result.json], {
713.         type: "application/json",
714.       }));
715.       const link = document.createElement("a");
716.       link.href = url;
717.       link.download = result.fileName;
718.       link.click();
719.       URL.revokeObjectURL(url);
720.       this.setStatus(`Exported ${result.fileName}.`, true);
721.     } catch (error: unknown) {
722.       this.setStatus(`Export failed: ${String(error)}`, false);
723.     }
724.   }
