726.   private openImportPicker(slotId: SaveSlotId, overwrite: boolean): void {
727.     this.importInput?.remove();
728.     const input = document.createElement("input");
729.     input.id = "save-slot-import-input";
730.     input.type = "file";
731.     input.accept = ".json,application/json";
732.     input.setAttribute("aria-label", `Import campaign into ${slotId}`);
733.     input.style.position = "fixed";
734.     input.style.left = "-10000px";
735.     input.addEventListener("change", async () => {
736.       const file = input.files?.[0];
737.       if (!file) return;
738.       try {
739.         this.applyResult(importSaveSlot(slotId, await file.text(), overwrite));
740.       } catch (error: unknown) {
741.         this.setStatus(`Import failed: ${String(error)}`, false);
742.       } finally {
743.         input.remove();
744.         if (this.importInput === input) this.importInput = null;
745.       }
746.     }, { once: true });
747.     document.body.append(input);
748.     this.importInput = input;
