113.   let groups = sceneGroups.get(scene);
114.   if (!groups) {
115.     groups = new Map<string, LayoutGroup>();
116.     sceneGroups.set(scene, groups);
117.   }
118.   container.setData("layoutGroupId", id);
119.   groups.set(id, { id, container, viewport });
