146. export function auditSceneLayout(scene: Phaser.Scene): {
147.   scene: string;
148.   groups: Record<string, LayoutAuditResult & { items: LayoutAuditItem[] }>;
149.   overlapCount: number;
150.   clippingCount: number;
151. } {
152.   const groups = sceneGroups.get(scene);
153.   const results: Record<
154.     string,
155.     LayoutAuditResult & { items: LayoutAuditItem[] }
156.   > = {};
157.   let overlapCount = 0;
158.   let clippingCount = 0;
159.   groups?.forEach((group) => {
160.     const items = collectGroupItems(group);
161.     const result = auditLayout(items, group.viewport);
162.     results[group.id] = { ...result, items };
163.     overlapCount += result.overlaps.length;
164.     clippingCount += result.clipping.length;
165.   });
166.   return {
167.     scene: scene.scene.key,
168.     groups: results,
169.     overlapCount,
170.     clippingCount,
171.   };
172. }
