177. function directionalAction(
178.   direction: "Up" | "Down" | "Left" | "Right",
179.   context: InputContext,
180. ): InputAction {
181.   const prefix = context === "exploration" ? "move" : "navigate";
182.   return `${prefix}${direction}` as InputAction;
183. }
