190. export function normalizeAnalogAxis(value: number, deadZone = 0.24): number {
191.   if (!Number.isFinite(value)) return 0;
192.   const clamped = Math.max(-1, Math.min(1, value));
193.   const magnitude = Math.abs(clamped);
194.   if (magnitude <= deadZone) return 0;
195.   const scaled = (magnitude - deadZone) / (1 - deadZone);
196.   return Math.sign(clamped) * scaled;
197. }
