199. export function mapKeyboardCode(
200.   code: string,
201.   context: InputContext,
202. ): InputAction | undefined {
203.   if (code === "Enter" || code === "Space") {
204.     return context === "exploration" ? "interact" : "confirm";
205.   }
206.   if (code.startsWith("Arrow")) {
207.     const direction = code.slice("Arrow".length) as
208.       | "Up"
209.       | "Down"
210.       | "Left"
211.       | "Right";
212.     return directionalAction(direction, context);
213.   }
214.   const wasd: Readonly<Record<string, "Up" | "Down" | "Left" | "Right">> = {
215.     KeyW: "Up",
216.     KeyS: "Down",
217.     KeyA: "Left",
218.     KeyD: "Right",
219.   };
220.   const direction = wasd[code];
221.   if (direction) return directionalAction(direction, context);
222.   if (context === "inventory") {
223.     const inventory: Readonly<Record<string, InputAction>> = {
224.       KeyR: "inventoryCycleSort",
225.       KeyF: "inventoryCycleFilter",
226.       Slash: "inventorySearch",
227.       KeyX: "inventoryTransfer",
228.     };
229.     if (inventory[code]) return inventory[code];
230.   }
231.   if (context === "codex" && code === "Slash") return "codexSearch";
232.   return KEYBOARD_SHORTCUTS[code];
233. }
