235. export function resolveGamepadAction(
236.   binding: StandardGamepadBinding,
237.   context: InputContext,
238. ): InputAction {
239.   if (!binding.action.startsWith("navigate") || context !== "exploration") {
240.     return binding.action;
241.   }
242.   return binding.action.replace("navigate", "move") as InputAction;
243. }
