250.   action: InputAction,
251.   context: InputContext,
252.   featureAvailable = true,
253. ): boolean {
254.   return featureAvailable
255.     && (
256.       !EXPLORATION_ONLY_TOUCH_ACTIONS.has(action)
257.       || context === "exploration"
258.     );
259. }
