261. export class InputContextStack {
262.   private readonly registrations = new Map<string, InputContextRegistration>();
263. 
264.   register(registration: InputContextRegistration): () => void {
265.     this.registrations.set(registration.id, registration);
266.     return () => this.registrations.delete(registration.id);
267.   }
268. 
269.   resolve(fallback: InputContext): InputContext {
270.     return [...this.registrations.values()]
271.       .filter((registration) => registration.enabled())
272.       .sort((a, b) => b.priority - a.priority)[0]?.context ?? fallback;
273.   }
274. 
275.   clear(): void {
276.     this.registrations.clear();
277.   }
278. }
