280. export class InputKeyOwnership {
281.   private readonly heldKeys = new Map<string, string>();
282.   private readonly ownerCounts = new Map<string, number>();
283. 
284.   acquire(token: string, key: string): boolean {
285.     if (this.heldKeys.has(token)) return false;
286.     this.heldKeys.set(token, key);
287.     const owners = this.ownerCounts.get(key) ?? 0;
288.     this.ownerCounts.set(key, owners + 1);
289.     return owners === 0;
290.   }
291. 
292.   release(token: string): { key: string; finalOwner: boolean } | null {
293.     const key = this.heldKeys.get(token);
294.     if (!key) return null;
295.     this.heldKeys.delete(token);
296.     const owners = this.ownerCounts.get(key) ?? 1;
297.     if (owners <= 1) {
298.       this.ownerCounts.delete(key);
299.       return { key, finalOwner: true };
300.     }
301.     this.ownerCounts.set(key, owners - 1);
302.     return { key, finalOwner: false };
303.   }
304. 
305.   clear(): string[] {
306.     const keys = [...this.ownerCounts.keys()];
307.     this.heldKeys.clear();
308.     this.ownerCounts.clear();
309.     return keys;
310.   }
311. }
