313. interface HeldInput {
314.   action: InputAction;
315.   source: InputSource;
316.   nextRepeatAt: number;
317. }
318. 
319. export class SemanticInputState {
320.   private readonly held = new Map<string, HeldInput>();
321.   private readonly lastDispatch = new Map<InputAction, number>();
322.   private currentSource: InputSource = "keyboard";
323. 
324.   constructor(
325.     private readonly repeatDelay = 320,
326.     private readonly repeatInterval = 110,
327.     private readonly duplicateWindow = 45,
328.   ) {}
329. 
330.   get source(): InputSource {
331.     return this.currentSource;
332.   }
333. 
334.   press(
335.     token: string,
336.     action: InputAction,
337.     source: InputSource,
338.     timestamp: number,
339.   ): SemanticInputEvent | null {
340.     if (this.held.has(token)) return null;
341.     this.currentSource = source;
342.     this.held.set(token, {
343.       action,
344.       source,
345.       nextRepeatAt: timestamp + this.repeatDelay,
346.     });
347.     return this.createEvent(action, source, timestamp, false, token);
348.   }
349. 
350.   pulse(
351.     action: InputAction,
352.     source: InputSource,
353.     timestamp: number,
354.   ): SemanticInputEvent | null {
355.     this.currentSource = source;
356.     return this.createEvent(action, source, timestamp, false);
357.   }
358. 
359.   release(token: string): void {
360.     this.held.delete(token);
361.   }
362. 
363.   update(timestamp: number): SemanticInputEvent[] {
364.     const events: SemanticInputEvent[] = [];
365.     for (const [token, held] of this.held) {
366.       if (
367.         !isRepeatableAction(held.action)
368.         || timestamp < held.nextRepeatAt
369.       ) {
370.         continue;
371.       }
372.       held.nextRepeatAt = timestamp + this.repeatInterval;
373.       const event = this.createEvent(
374.         held.action,
375.         held.source,
376.         timestamp,
377.         true,
378.         token,
379.       );
380.       if (event) events.push(event);
381.     }
382.     return events;
383.   }
384. 
385.   clearSource(source: InputSource): void {
386.     for (const [token, held] of this.held) {
387.       if (held.source === source) this.held.delete(token);
388.     }
389.   }
390. 
391.   releaseMatching(tokenPrefix: string): Array<{
392.     token: string;
393.     action: InputAction;
394.   }> {
395.     const released: Array<{ token: string; action: InputAction }> = [];
396.     for (const [token, held] of this.held) {
397.       if (!token.startsWith(tokenPrefix)) continue;
398.       released.push({ token, action: held.action });
399.       this.held.delete(token);
400.     }
401.     return released;
402.   }
403. 
404.   clear(): void {
405.     this.held.clear();
406.     this.lastDispatch.clear();
407.   }
408. 
409.   private createEvent(
410.     action: InputAction,
411.     source: InputSource,
412.     timestamp: number,
413.     repeated: boolean,
414.     token?: string,
415.   ): SemanticInputEvent | null {
416.     const last = this.lastDispatch.get(action);
417.     if (last !== undefined && timestamp - last < this.duplicateWindow) {
418.       return null;
419.     }
420.     this.lastDispatch.set(action, timestamp);
421.     return { action, source, timestamp, repeated, token };
422.   }
423. }
424. 
