30. /** Calculate centered panel dimensions relative to the camera viewport. */
31. export function calcPanelLayout(
32.   scene: Phaser.Scene,
33.   panelW: number,
34.   panelH: number,
35.   offsetY = 0,
36.   safeArea: Partial<LayoutInsets> = {},
37. ): PanelLayout {
38.   const w = scene.cameras.main.width;
