41.     { x: 0, y: 0, width: w, height: h },
42.     { width: panelW, height: panelH },
43.     safeArea,
44.   );
45.   return {
46.     w,
47.     h,
48.     panelW: panel.width,
49.     panelH: panel.height,
50.     px: panel.x,
51.     py: panel.y + offsetY,
52.   };
53. }
